public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    int count = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                count++;
                markDeposit(grid, i, j);
            }
        }
    }

    return count;
}

private static void markDeposit(char[][] grid, int i, int j) {
    int rows = grid.length;
    int cols = grid[0].length;

    if (i < 0 || i >= rows || j < 0 || j >= cols || grid[i][j] != '@') {
        return;
    }

    grid[i][j] = '*';

    markDeposit(grid, i - 1, j); // up
    markDeposit(grid, i + 1, j); // down
    markDeposit(grid, i, j - 1); // left
    markDeposit(grid, i, j + 1); // right
    markDeposit(grid, i - 1, j - 1); // up-left
    markDeposit(grid, i - 1, j + 1); // up-right
    markDeposit(grid, i + 1, j - 1); // down-left
    markDeposit(grid, i + 1, j + 1); // down-right
}

