    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        graph[edge[0]].add(edge[1]);
        graph[edge[1]].add(edge[0]);
    }
    return dfs(0, -1, graph, hasApple) * 2;
}

private int dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple) {
    int time = 0;
    for (int neighbor : graph[node]) {
        if (neighbor == parent) continue;
        time += dfs(neighbor, node, graph, hasApple);
    }
    if ((time > 0 || hasApple[node]) && node != 0) {
        return time + 1;
    }
    return time;
}

