public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }
    double sum = 0;
    for (int num : nums) {
        sum += num;
    }
    for (int i = 1; i < n; i++) {
        if ((i * sum) % n == 0) {
            return true;
        }
    }
    boolean[][] dp = new boolean[n + 1][n + 1];
    dp[0][0] = true;
    for (int i = 1; i <= n; i++) {
        dp[i][0] = true;
        int num = nums[i - 1];
        for (int j = 1; j <= n; j++) {
            if (j >= num) {
                dp[i][j] = dp[i - 1][j] || dp[i - 1][j - num];
            }
        }
    }
    for (int i = 1; i < n; i++) {
        for (int j = i; j <= n; j++) {
            if (dp[i][j] && (j * sum) % n == 0) {
                return true;
            }
        }
    }
    return false;
}

