public int findMinFibonacciNumbers(int k) {
    List<Integer> fib = new ArrayList<>();
    int a = 1, b = 1;
    fib.add(a);
    fib.add(b);

    // Generate Fibonacci numbers up to k
    while (b + a <= k) {
        int next = a + b;
        fib.add(next);
        a = b;
        b = next;
    }

    int count = 0;
    int index = fib.size() - 1;

    // Find the minimum number of Fibonacci numbers whose sum is k
    while (k > 0) {
        if (fib.get(index) <= k) {
            k -= fib.get(index);
            count++;
        }
        index--;
    }

    return count;
}

