public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int remainingSum = k;

    for (int i = 0; i < n; i++) {
        if (remainingSum == n - i) {
            // If remaining sum is equal to the number of remaining characters, the smallest character is 'a'
            result.append('a');
            remainingSum--;
        } else if (remainingSum < n - i) {
            // If remaining sum is less than the number of remaining characters, append the corresponding character
            result.append((char) ('a' + remainingSum - 1));
            remainingSum = 0;
        } else {
            // Otherwise, append 'z' and subtract 26 from the remaining sum
            result.append('z');
            remainingSum -= 26;
        }
    }

    return result.reverse().toString();
}

