public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) {
            return result;
        }

        Queue<Integer> que = new LinkedList<>();
        for (int i = 1; i <= 9; i++) {
            que.offer(i);
        }

        while (!que.isEmpty()) {
            int num = que.poll();
            if (num <= high && num >= low) {
                result.add(num);
            }
            if (num == 0 || num > high) {
                continue;
            }
            int lastDigit = num % 10;
            if (lastDigit > 0) {
                que.offer(num * 10 + lastDigit - 1);
            }
            if (lastDigit < 9) {
                que.offer(num * 10 + lastDigit + 1);
            }
        }

        return result;
    }

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    long lowerNumbers = n;
    long currentDigit = 0;
    long higherNumbers = 0;

    while (lowerNumbers > 0 || currentDigit > 0) {
        lowerNumbers = n - (n / factor) * factor;
        currentDigit = (n / factor) % 10;
        higherNumbers = n / (factor * 10);

        if (currentDigit == 0) {
            count += higherNumbers * factor;
        } else if (currentDigit == 1) {
            count += higherNumbers * factor + lowerNumbers + 1;
        } else {
            count += (higherNumbers + 1) * factor;
        }

        factor *= 10;
    }

    return (int) count;
}

