public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;

    int[][][] directions = {
        {{0, 1}},  // Horizontal
        {{1, 0}},  // Vertical
        {{1, 1}},  // Diagonal
        {{1, -1}}  // Anti-diagonal
    };

    for (int[] direction : directions) {
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    int len = 1;

                    for (int k = 1; k < m || k < n; k++) {
                        int newRow = i + direction[0][0] * k;
                        int newCol = j + direction[0][1] * k;

                        if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n && mat[newRow][newCol] == 1) {
                            len++;
                        } else {
                            break;
                        }
                    }

                    maxLen = Math.max(maxLen, len);
                }
            }
        }
    }

    return maxLen;
}

