}

private static int helper(int[] A, int start, int target) {
    if (start == A.length - 1) {
        int sum = A[start] + A[0];
        return isPerfectSquare(sum) ? 1 : 0;
    }

    int count = 0;
    for (int i = start + 1; i < A.length; i++) {
        int sum = A[start] + A[i];
        if (isPerfectSquare(sum)) {
            int temp = A[start + 1];
            A[start + 1] = A[i];
            A[i] = temp;
            count += helper(A, start + 2, A[start]);
            temp = A[start + 1];
            A[start + 1] = A[i];
            A[i] = temp;
        }
    }

    return count;
}

private static boolean isPerfectSquare(int num) {
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];

    // Fill left array
    left[0] = -1;
    for (int i = 1; i < n; i++) {
        int p = i - 1;
        while (p >= 0 && heights[p] >= heights[i]) {
            p = left[p];
        }
        left[i] = p;
    }

    // Fill right array
    right[n - 1] = n;
    for (int i = n - 2; i >= 0; i--) {
        int p = i + 1;
        while (p < n && heights[p] >= heights[i]) {
            p = right[p];
        }
        right[i] = p;
    }

    // Calculate the maximum area
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] - 1));
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Move up
            int r = Math.min(d, rows - 1);
            int c = d - r;
            while (r >= 0 && c < cols) {
                result[index++] = mat[r--][c++];
            }
        } else {
            // Move down
            int c = Math.min(d, cols - 1);
            int r = d - c;
            while (r < rows && c >= 0) {
                result[index++] = mat[r++][c--];
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Find the first place from the right where the digits are not in ascending order
    int i;
    for (i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such place is found, no rearrangement can be smaller than n
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of (i-th digit) which is greater than digits[i]
    int j;
    for (j = len - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the above found smallest digit with digits[i]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the (i-th digit) in ascending order
    Arrays.sort(digits, i + 1, len);

    // Convert the digits back to a number
    return Integer.parseInt(new String(digits));
}

public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n == 0) {
            return result;
        }
        if (n == 1) {
            result.add("0");
            result.add("1");
            result.add("8");
            return result;
        }
        helper(result, new char[n], 0, n - 1);
        return result;
    }

private static void helper(List<String> result, char[] num, int left, int right) {
        if (left > right) {
            result.add(new String(num));
            return;
        }

        char[] symmetricPairs = {'0', '1', '6', '8', '9'};
        if (left == right) {
            symmetricPairs = new char[]{'0', '1', '8'};
        }

        for (char c : symmetricPairs) {
            if (left == 0 && c == '0' && left != right) {
                continue;
            }
            num[left] = c;
            if (left != right) {
                num[right] = getSymmetric(c);
            }
            helper(result, num, left + 1, right - 1);
        }
    }

private static char getSymmetric(char c) {
        switch (c) {
            case '6':
                return '9';
            case '9':
                return '6';
            default:
                return c;
        }
    }

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    return (y2 - y1) * (x3 - x1) != (y3 - y1) * (x2 - x1);
}

public static int findNthUglyNumber(int n) {
        if (n <= 0) return -1;
        int[] uglyNumbers = new int[n];
        uglyNumbers[0] = 1;
        int i2 = 0, i3 = 0, i5 = 0;
        int nextMultipleOf2 = 2;
        int nextMultipleOf3 = 3;
        int nextMultipleOf5 = 5;
        int nextUglyNumber = 1;

        for (int i = 1; i < n; i++) {
            nextUglyNumber = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
            uglyNumbers[i] = nextUglyNumber;

            if (nextUglyNumber == nextMultipleOf2) {
                i2++;
                nextMultipleOf2 = uglyNumbers[i2] * 2;
            }
            if (nextUglyNumber == nextMultipleOf3) {
                i3++;
                nextMultipleOf3 = uglyNumbers[i3] * 3;
            }
            if (nextUglyNumber == nextMultipleOf5) {
                i5++;
                nextMultipleOf5 = uglyNumbers[i5] * 5;
            }
        }
        return nextUglyNumber;
    }

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
    }

    maxEnergy = Math.max(maxEnergy, currentEnergy);

    return maxEnergy;
}

